CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,timezone text NOT NULL DEFAULT 'UTC',settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email citext NOT NULL UNIQUE,password_hash text NOT NULL,name text NOT NULL,avatar_url text,phone text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','manager','agent','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS pipelines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,description text,is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pipeline_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pipeline_id uuid NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,name text NOT NULL,position integer NOT NULL,probability integer NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),color text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(pipeline_id,position));
CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,email text,phone text,website text,industry text,owner_id uuid REFERENCES users(id) ON DELETE SET NULL,custom_fields jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,first_name text NOT NULL,last_name text,email text,phone text,job_title text,account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,owner_id uuid REFERENCES users(id) ON DELETE SET NULL,custom_fields jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,first_name text NOT NULL,last_name text,email text,phone text,source text NOT NULL DEFAULT 'manual',status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','converted','lost')),owner_id uuid REFERENCES users(id) ON DELETE SET NULL,score integer NOT NULL DEFAULT 0,custom_fields jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,amount numeric(14,2) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'INR',stage text NOT NULL DEFAULT 'new',probability integer NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),expected_close_date date,pipeline_id uuid REFERENCES pipelines(id) ON DELETE SET NULL,account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,owner_id uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title text NOT NULL,description text,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','completed','cancelled')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),due_at timestamptz,assigned_to uuid REFERENCES users(id) ON DELETE SET NULL,related_type text,related_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,body text NOT NULL,related_type text,related_id uuid,created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,color text,UNIQUE(workspace_id,name));
CREATE TABLE IF NOT EXISTS entity_tags(tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE CASCADE,entity_type text NOT NULL,entity_id uuid NOT NULL,PRIMARY KEY(tag_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,channel text NOT NULL CHECK(channel IN ('whatsapp','sms','email','call','web')),external_contact text,subject text,status text NOT NULL DEFAULT 'open',assigned_to uuid REFERENCES users(id) ON DELETE SET NULL,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,last_message_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id uuid REFERENCES users(id) ON DELETE SET NULL,direction text NOT NULL CHECK(direction IN ('inbound','outbound')),message_type text NOT NULL DEFAULT 'text',body text,media_url text,external_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,direction text NOT NULL CHECK(direction IN ('inbound','outbound')),status text NOT NULL DEFAULT 'completed',phone text,duration_seconds integer NOT NULL DEFAULT 0,recording_url text,started_at timestamptz,ended_at timestamptz,agent_id uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,channel text,status text NOT NULL DEFAULT 'draft',settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS automations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,trigger_type text NOT NULL,active boolean NOT NULL DEFAULT false,definition jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS automation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,automation_id uuid REFERENCES automations(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'queued',run_at timestamptz NOT NULL DEFAULT now(),payload jsonb NOT NULL DEFAULT '{}',error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,body text,read_at timestamptz,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,entity text NOT NULL,entity_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS leads_workspace_idx ON leads(workspace_id);CREATE INDEX IF NOT EXISTS contacts_workspace_idx ON contacts(workspace_id);CREATE INDEX IF NOT EXISTS accounts_workspace_idx ON accounts(workspace_id);CREATE INDEX IF NOT EXISTS opportunities_workspace_idx ON opportunities(workspace_id);CREATE INDEX IF NOT EXISTS tasks_workspace_idx ON tasks(workspace_id);CREATE INDEX IF NOT EXISTS conversations_workspace_idx ON conversations(workspace_id);CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id,created_at);CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at);CREATE INDEX IF NOT EXISTS audit_workspace_idx ON audit_logs(workspace_id,created_at);